import * as s from "../core/validation/index.js";
import type { JsonValue, Schema } from "../core/validation/schema.js";
import {
  sourceApiAssociationConfigSchema,
  type SourceApiAssociationConfig,
} from "./source-api-association-config.js";

export type V1MergedApisSourceApiAssociationsRequest = {
  /**
   * The identifier of the AppSync Source API. This is generated by the AppSync service. In most
   * cases, source APIs (especially in your account) only require the API ID value or ARN of the
   * source API. However, source APIs from other accounts (cross-account use cases) strictly require
   * the full resource ARN of the source API.
   */
  sourceApiIdentifier: string;
  /** The description field. */
  description?: string;
  sourceApiAssociationConfig?: SourceApiAssociationConfig;
  /** Properties the service sent or accepts beyond those declared. */
  additionalProperties?: Record<string, JsonValue>;
};

export const v1MergedApisSourceApiAssociationsRequestSchema: Schema<V1MergedApisSourceApiAssociationsRequest> =
  s.object<V1MergedApisSourceApiAssociationsRequest>(
    {
      sourceApiIdentifier: s.string(),
      description: s.optional(s.string()),
      sourceApiAssociationConfig: s.optional(s.lazy(() => sourceApiAssociationConfigSchema)),
    },
    { additionalProperties: s.json() },
  );
